using System;
using System.Linq;
using NUnit.Framework;
using LegendsOfRus.GameplayCore;
namespace LegendsOfRus.Tests
{
    public class MechanicsPrototypeTests
    {
        static BoardModel Board(){var m=new BoardModel(8,7,6,new SeededBoardRandom(1));for(int y=0;y<7;y++)for(int x=0;x<8;x++)m.SetCell(new BoardPosition(x,y),new BoardCellData((x+2*y)%6,SpecialGemKind.None));return m;}
        static BoardResolutionPlanner Candidate(BoardModel m)=>new BoardResolutionPlanner(m,null,GameplayRuleVersion.PrototypeR1);
        [TestCase(SpecialGemKind.Row,8)][TestCase(SpecialGemKind.Column,7)][TestCase(SpecialGemKind.Burst,25)]
        public void TapHasExactFootprintAndOneMove(SpecialGemKind kind,int count){var m=Board();var at=new BoardPosition(3,3);m.SetCell(at,new BoardCellData(1,kind));string before=m.ComputeStateHash();var p=Candidate(m).PlanTapSpecial(at);Assert.That(p.IsResolved,Is.True);Assert.That(p.ConsumesMove,Is.True);Assert.That(p.Waves[0].ClearedCells.Count,Is.EqualTo(count));Assert.That(m.ComputeStateHash(),Is.EqualTo(before));Assert.That(new BoardResolutionPlanner(m).PlanTapSpecial(at).IsResolved,Is.False);}
        [Test] public void EdgeBlastIsClipped(){var m=Board();m.SetCell(new BoardPosition(0,0),new BoardCellData(1,SpecialGemKind.Burst));Assert.That(Candidate(m).PlanTapSpecial(new BoardPosition(0,0)).Waves[0].ClearedCells.Count,Is.EqualTo(9));}
        [Test] public void BlockedAndOrdinaryTapsDoNotSpend(){var m=Board();var p=new BoardPosition(3,3);Assert.That(Candidate(m).PlanTapSpecial(p).ConsumesMove,Is.False);m.SetCell(p,new BoardCellData(1,SpecialGemKind.Row));m.SetObstacle(p,new BoardObstacleData(BoardObstacleKind.Chain,1));Assert.That(Candidate(m).PlanTapSpecial(p).IsResolved,Is.False);}
        [Test] public void ColorTapUsesMostCommonColor(){var m=Board();var p=new BoardPosition(3,3);m.SetCell(p,new BoardCellData(5,SpecialGemKind.Color));var counts=Enumerable.Range(0,6).Select(c=>Enumerable.Range(0,56).Count(i=>m.GetTile(new BoardPosition(i%8,i/8))==c)).ToArray();int color=Array.IndexOf(counts,counts.Max());var result=Candidate(m).PlanTapSpecial(p);Assert.That(result.Waves[0].Activations[0].TileType,Is.EqualTo(color));Assert.That(result.Waves[0].ClearedCells.All(c=>c.Position==p||c.Cell.TileType==color),Is.True);}
        [Test] public void LineCombinationIsExactCross(){var m=Board();var a=new BoardPosition(3,3);var b=new BoardPosition(4,3);m.SetCell(a,new BoardCellData(1,SpecialGemKind.Row));m.SetCell(b,new BoardCellData(2,SpecialGemKind.Row));var first=Candidate(m).PlanSwap(a,b).Waves[0];Assert.That(first.ClearedCells.Count,Is.EqualTo(14));Assert.That(first.ClearedCells.All(c=>c.Position.X==4||c.Position.Y==3),Is.True);}
        [TestCase(SpecialGemKind.Row)][TestCase(SpecialGemKind.Column)]public void LineBombIsThreeRowsAndColumns(SpecialGemKind kind){var m=Board();var a=new BoardPosition(3,3);var b=new BoardPosition(4,3);m.SetCell(a,new BoardCellData(1,kind));m.SetCell(b,new BoardCellData(2,SpecialGemKind.Burst));var first=Candidate(m).PlanSwap(a,b).Waves[0];Assert.That(first.ClearedCells.Count,Is.EqualTo(36));Assert.That(first.ClearedCells.All(c=>Math.Abs(c.Position.X-3)<=1||Math.Abs(c.Position.Y-3)<=1),Is.True);}
        [Test] public void FourCreationIsOppositeOnlyInCandidate(){var m=Board();for(int x=1;x<=4;x++)m.SetCell(new BoardPosition(x,2),new BoardCellData(2,SpecialGemKind.None));var runs=m.FindRuns();Assert.That(m.DetermineSpecialCreations(runs,new BoardPosition(3,2))[new BoardPosition(3,2)],Is.EqualTo(SpecialGemKind.Row));Assert.That(m.DetermineSpecialCreations(runs,new BoardPosition(3,2),true)[new BoardPosition(3,2)],Is.EqualTo(SpecialGemKind.Column));}
        [Test] public void TapReplayPinsVersionAndHash(){var m=Board();var p=new BoardPosition(3,3);m.SetCell(p,new BoardCellData(1,SpecialGemKind.Burst));var record=new MechanicsReplayCommand{Rules=GameplayRuleVersion.PrototypeR1,BeforeToken=m.CreateSnapshot().ToReplayToken(),Tap=true,X=3,Y=3};var plan=record.Resolve();record.ExpectedPlanHash=plan.PlanHash;Assert.That(record.Resolve().FinalSnapshot.StateHash,Is.EqualTo(plan.FinalSnapshot.StateHash));record.Rules=GameplayRuleVersion.Legacy;Assert.Throws<InvalidOperationException>(()=>record.Resolve());record.Rules=(GameplayRuleVersion)999;Assert.Throws<ArgumentException>(()=>record.Resolve());}
        [Test] public void BlastHitsOneObstacleLayer(){var m=Board();m.SetCell(new BoardPosition(3,3),new BoardCellData(1,SpecialGemKind.Burst));m.SetObstacle(new BoardPosition(3,4),new BoardObstacleData(BoardObstacleKind.Ice,2));var first=Candidate(m).PlanTapSpecial(new BoardPosition(3,3)).Waves[0];Assert.That(first.ObstacleInteractions.Single().LayersAfter,Is.EqualTo(1));}
    }
}
